where not exists (select 1 from public.trainers where slug = 'sally-samad-personal-training-watford' and status = 'removed')
on conflict (slug) do update set name = excluded.name, business_name = excluded.business_name, headline = excluded.headline, bio = excluded.bio, city = excluded.city, region = excluded.region, postcode_district = excluded.postcode_district, location = excluded.location, in_person = excluded.in_person, online = excluded.online, home_visits = excluded.home_visits, price_from = excluded.price_from, price_to = excluded.price_to, qualifications = excluded.qualifications, years_experience = excluded.years_experience, website = excluded.website, email = excluded.email, phone = excluded.phone, instagram = excluded.instagram, image_url = excluded.image_url, free_consultation = excluded.free_consultation, sports = excluded.sports, source = excluded.source, source_url = excluded.source_url, source_licence = excluded.source_licence, last_verified_at = excluded.last_verified_at, is_sample = excluded.is_sample
  where public.trainers.claimed_by is null and public.trainers.status <> 'removed';
delete from public.trainer_styles where trainer_id = (select id from public.trainers where slug = 'sally-samad-personal-training-watford' and claimed_by is null);
delete from public.trainer_goals where trainer_id = (select id from public.trainers where slug = 'sally-samad-personal-training-watford' and claimed_by is null);
insert into public.trainer_styles (trainer_id, style_slug) select id, s from public.trainers, unnest(array['strength']::text[]) s where slug = 'sally-samad-personal-training-watford' and claimed_by is null and status = 'published' on conflict do nothing;
insert into public.trainer_goals (trainer_id, goal_slug) select id, g from public.trainers, unnest(array['weight-loss', 'muscle-gain', 'pre-post-natal']::text[]) g where slug = 'sally-samad-personal-training-watford' and claimed_by is null and status = 'published' on conflict do nothing;

-- Tarrant Trainer
insert into public.trainers (slug, name, business_name, headline, bio, city, region, postcode_district, location, in_person, online, home_visits, price_from, price_to, qualifications, years_experience, website, email, phone, instagram, image_url, free_consultation, sports, source, source_url, source_licence, last_verified_at, is_sample, status)
select 'tarrant-trainer-watford', 'Tarrant Trainer', 'Tarrant Trainer', 'Personal training in Rickmansworth and Chorleywood', 'Tarrant Trainer has more than 15 years of experience helping people get stronger and fitter across Rickmansworth, Chorleywood, Croxley Green and Watford, training at a gym, at home, in a home gym or outdoors.', 'Watford', 'Hertfordshire', 'WD3', extensions.st_setsrid(extensions.st_makepoint(-0.4824, 51.6468), 4326)::extensions.geography, true, false, true, null, null, '{}'::text[], null, 'https://tarranttrainer.co.uk/', null, null, null, null, false, '{}'::text[], 'website', 'https://tarranttrainer.co.uk/', 'Business details published on the trainer''s own website', now(), false, 'published'
where not exists (select 1 from public.trainers where slug = 'tarrant-trainer-watford' and status = 'removed')
on conflict (slug) do update set name = excluded.name, business_name = excluded.business_name, headline = excluded.headline, bio = excluded.bio, city = excluded.city, region = excluded.region, postcode_district = excluded.postcode_district, location = excluded.location, in_person = excluded.in_person, online = excluded.online, home_visits = excluded.home_visits, price_from = excluded.price_from, price_to = excluded.price_to, qualifications = excluded.qualifications, years_experience = excluded.years_experience, website = excluded.website, email = excluded.email, phone = excluded.phone, instagram = excluded.instagram, image_url = excluded.image_url, free_consultation = excluded.free_consultation, sports = excluded.sports, source = excluded.source, source_url = excluded.source_url, source_licence = excluded.source_licence, last_verified_at = excluded.last_verified_at, is_sample = excluded.is_sample
  where public.trainers.claimed_by is null and public.trainers.status <> 'removed';
delete from public.trainer_styles where trainer_id = (select id from public.trainers where slug = 'tarrant-trainer-watford' and claimed_by is null);
delete from public.trainer_goals where trainer_id = (select id from public.trainers where slug = 'tarrant-trainer-watford' and claimed_by is null);
insert into public.trainer_styles (trainer_id, style_slug) select id, s from public.trainers, unnest(array['strength', 'functional']::text[]) s where slug = 'tarrant-trainer-watford' and claimed_by is null and status = 'published' on conflict do nothing;
insert into public.trainer_goals (trainer_id, goal_slug) select id, g from public.trainers, unnest(array['general-fitness', 'confidence', 'weight-loss']::text[]) g where slug = 'tarrant-trainer-watford' and claimed_by is null and status = 'published' on conflict do nothing;

commit;

select count(*) as real_trainers from public.trainers where is_sample = false and status = 'published';
